 if(a==='dash-reset'){S.dashboard=LocalAnalytics.init(C.dateNow());renderOverview();return}if(a==='dash-export'){const rows=LocalAnalytics.rows(S.data,S.dashboard);downloadText(csv([['索赔编号','日期','产品','型号','客户','索赔金额','减免金额','实际赔付','部门','状态'],...rows.map(r=>[r.id,r.date,r.product,r.model,r.customer,claimMoney(r,'amount'),claimMoney(r,'waiver'),claimMoney(r,'actual'),r.dept,r.status])]),'索赔当前范围.csv');return}if(a==='metric-refresh'){S.period=$('#metricPeriod').value;S.date=$('#metricDate').value;await renderClosure();return}
